import fs from 'node:fs';import{gzipSync}from'node:zlib';import{pathToFileURL}from'node:url';
const base=new URL('.',pathToFileURL(process.argv[2]));const{McpHost}=await import(new URL('host.js',base));const{DeterministicLiveSimulator,LiveMutationNotDispatchedError}=await import(new URL('live.js',base));
function clean(v){v=structuredClone(v);function walk(x){if(!x||typeof x!=='object')return;for(const[k,w]of Object.entries(x)){if(typeof w==='string'&&w.startsWith('automation_'))x[k]='$transaction';else if(k==='expiresAt')x[k]='$time';else walk(w);}}if(v?.result?.content?.[0]?.text)try{v.result.content[0].text=JSON.parse(v.result.content[0].text);}catch{}walk(v);return v;}

const pref='parameter:gain-1';const kinds=['create-absent','create-existing','delete-existing','delete-absent','insert-existing','insert-absent','step-existing','step-absent','step-identical','range-existing','range-empty','clear-existing','clear-empty','arrangement-insert'];
function setup(sim,kind){const clip=sim.state.tracks[0].clips[0];if(!kind.endsWith('absent')&&!kind.endsWith('empty'))clip.envelopes={[pref]:[{value:0.2,time:0.5},{time:1,value:0.7},{time:2,value:0.3},{time:3,value:0.8}]};if(kind==='step-identical')clip.envelopes={[pref]:[{time:1,value:0.6},{time:2,value:0.6}]};if(kind==='clear-existing')clip.envelopes['parameter:volume:track-1']=[{time:0,value:0.5}];if(kind.startsWith('arrangement'))sim.state.arrangementClips.push({trackRef:'track:track-1',clip:{...structuredClone(clip),ref:'arrangement-clip:track-1:0',objectIdentity:'simulator:arrangement-clip:0'}});}
function params(kind){const action=kind.startsWith('create')?'create-envelope':kind.startsWith('delete')?'delete-envelope':kind.startsWith('step')?'insert-step':kind.startsWith('range')?'delete-range':kind.startsWith('clear')?'clear-envelopes':'insert';return{action,clipRef:kind.startsWith('arrangement')?'arrangement-clip:track-1:0':'clip:clip-1',...(action==='clear-envelopes'?{}:{parameterRef:pref}),...(action==='insert'?{points:[{value:0.6,time:1},{time:2,value:0.4}]}:{}),...(action==='insert-step'?{start:1,length:1,value:0.6}:{}),...(action==='delete-range'?{from:0.5,to:2}:{})};}
const rows=[];for(const kind of ['create-absent','delete-existing','insert-existing','step-existing','range-existing','clear-existing'])for(const action of ['preview','apply']){const valid=action==='preview'?params(kind):{transactionId:'missing',confirmation:'apply',idempotencyKey:'apply-key'};const cases=[null,[],{},0,false,'x',valid,{...valid,extra:true}];for(const key of action==='preview'?['action','clipRef','parameterRef','points','from','to','start','length','value']:Object.keys(valid)){const omitted={...valid};delete omitted[key];cases.push(omitted);for(const value of [null,[],{},false,true,-1,0,0.000999,0.001,0.5,1,2,1e308,'','x','a'.repeat(257)])cases.push({...valid,[key]:value});}if(action==='preview'&&kind==='insert-existing'){for(const value of [null,[],{},false,true,{time:0},{value:0},{time:-1,value:0},{time:0,value:null},{time:0,value:0,extra:1}])cases.push({...valid,points:[value]});cases.push({...valid,points:Array.from({length:513},(_,time)=>({time,value:0.5}))});}for(const args of cases){const sim=new DeterministicLiveSimulator();setup(sim,kind);const host=new McpHost(sim);rows.push({kind,action,args,result:clean(await host[action==='preview'?'liveAutomationPreviewAsync':'liveAutomationApplyAsync'](1,args))});}}
const workflows=[];for(const kind of kinds)for(const scenario of ['normal','expire','epoch','identity-edit','parameter-identity','source-content','unrelated-content','missing-identity','apply-before','apply-after','apply-refusal','apply-no-effect','apply-read','apply-current-read','apply-preabort','apply-silent-no-effect','apply-corrupt-result','undo-before','undo-after','undo-refusal','undo-no-effect','undo-read','undo-current-read','undo-second-before','undo-second-after','undo-second-refusal','undo-second-no-effect','undo-other-identity','undo-other-content','undo-epoch']){
const sim=new DeterministicLiveSimulator(),calls=[],cache=new Map();setup(sim,kind);let fault='',fired=false,afterInvoke=false,mutations=0;const source=kind.startsWith('arrangement')?sim.state.arrangementClips[0].clip:sim.state.tracks[0].clips[0];if(scenario==='missing-identity')delete source.objectIdentity;
function context(c){return c?{deadline:c.deadlineMs!==undefined,...(c.idempotencyKey?{idempotencyKey:c.idempotencyKey}:{}),...(c.transactionId?{transactionId:c.transactionId}:{})}:null;}
function readFault(){if(!fired&&((fault.endsWith('-read')&&afterInvoke)||fault==='apply-current-read'||fault==='undo-current-read')){fired=true;throw Error('injected authoritative read failure');}}
function invoke(i,c){calls.push(clean({method:'invoke',invocation:i,context:context(c)}));if(i.operation==='automation.envelope.read'){readFault();return sim.invoke(i);}const key=JSON.stringify([c?.transactionId,c?.idempotencyKey,i]);if(cache.has(key))return cache.get(key);mutations++;const selected=!fault.includes('second')||mutations===2;if(selected&&!fired&&['before','refusal'].some(s=>fault.endsWith(s))){fired=true;throw fault.endsWith('refusal')?new LiveMutationNotDispatchedError('mutation was not dispatched: ownership changed'):Error('injected operation failure');}const noEffect=selected&&!fired&&fault.endsWith('no-effect');const result=noEffect?{ok:true}:sim.invoke(i);if(noEffect)fired=true;else cache.set(key,structuredClone(result));afterInvoke=true;if(selected&&!fired&&fault.endsWith('after')){fired=true;throw Error('injected operation failure');}if(!fired&&fault==='apply-corrupt-result'){fired=true;result.cleared=999;result.envelopesRevision='wrong';result.inserted=0;}return result;}
const adapter={status:()=>sim.status(),snapshot:()=>sim.snapshot(),get:r=>sim.get(r),invoke:i=>invoke(i),subscribe:l=>sim.subscribe(l),reconnect:()=>sim.reconnect(),snapshotAsync:async(c,r)=>{calls.push(clean({method:'snapshot',request:r??null,context:context(c)}));readFault();return sim.snapshotAsync(c,r)},discoverAsync:async(r,c)=>{calls.push(clean({method:'discover',request:r,context:context(c)}));readFault();return sim.discoverAsync(r,c)},getAsync:async(r,c)=>{calls.push(clean({method:'get',reference:r,context:context(c)}));readFault();return sim.get(r)},invokeAsync:async(i,c)=>invoke(i,c),refreshStatusAsync:async(c)=>{calls.push(clean({method:'status',context:context(c)}));return sim.status()}};
const host=new McpHost(adapter),results=[],states=[];const preview=await host.liveAutomationPreviewAsync(1,params(kind));results.push(clean(preview));const body=preview.result?.content?.[0]?.text?JSON.parse(preview.result.content[0].text):{};const txid=body.transactionId;
if(txid){const record=host.clipLifecycleTransactions.get(txid);async function perform(action,key){const args={transactionId:txid,confirmation:action,idempotencyKey:key};const controller=new AbortController();if(scenario==='apply-preabort')controller.abort();results.push(clean(action==='apply'?await host.liveAutomationApplyAsync(results.length+1,args,controller.signal):await host.liveUndoAsync(results.length+1,args)));states.push(clean(record));}
if(scenario==='expire')record.expiresAt=0;if(scenario==='epoch')sim.reconnect();if(scenario==='identity-edit')source.objectIdentity='other';if(scenario==='parameter-identity')sim.state.tracks[0].devices[0].parameters[0].objectIdentity='other';if(scenario==='source-content'){source.envelopes??={};source.envelopes[pref]=[{time:1,value:0.99}];}if(scenario==='unrelated-content')source.name='Manual';if(scenario.startsWith('apply-'))fault=scenario;
for(const key of ['apply-key','other-key','apply-key'])await perform('apply',key);fault='';fired=false;afterInvoke=false;mutations=0;
if(scenario==='undo-other-identity')source.objectIdentity='other';if(scenario==='undo-other-content'){source.envelopes??={};source.envelopes[pref]=[{time:1,value:0.99}];}if(scenario==='undo-epoch')sim.reconnect();if(scenario.startsWith('undo-')&&!['undo-other-identity','undo-other-content','undo-epoch'].includes(scenario))fault=scenario;
for(const key of ['undo-key','other-undo-key','undo-key'])await perform('undo',key);fault='';fired=false;afterInvoke=false;mutations=0;await perform('undo','undo-key');await perform('undo','new-undo-key');}
workflows.push({kind,scenario,results,states,calls,state:sim.state});}

const evidence=[];for(const read of [null,[],{},false,3,'x',{available:false},{available:true},{available:true,revision:''},{available:true,revision:'x'},{available:true,revision:'x',exists:true,points:null},{available:true,revision:'x',exists:false,points:{}},{available:true,revision:'x',exists:0,points:[null]},{available:true,revision:'x',exists:true,points:[{extra:5,time:1,value:0.5}]}]){const sim=new DeterministicLiveSimulator();setup(sim,'insert-existing');const state=structuredClone(sim.state);sim.invokeAsync=async()=>structuredClone(read);const host=new McpHost(sim);const args=params('insert-existing');evidence.push({read,state,args,result:clean(await host.liveAutomationPreviewAsync(1,args))});}
const authorities=[];for(const variant of ['mixer-volume','mixer-pan','mixer-send','nested-chain','nested-pad','rack-macro','duplicate-parameter','conflicting-parameter','missing-parameter-identity','missing-device-identity','missing-track-identity','clear-nested','clear-duplicate','clear-macros']){const sim=new DeterministicLiveSimulator();setup(sim,'insert-existing');const track=sim.state.tracks[0],device=track.devices[0],clip=track.clips[0];let args=params('insert-existing');if(variant.startsWith('mixer')){args.parameterRef=variant==='mixer-volume'?track.mixer.volumeRef:variant==='mixer-pan'?track.mixer.panRef:track.mixer.sendRefs[0];if(typeof args.parameterRef!=='string')continue;}
if(['nested-chain','nested-pad','clear-nested'].includes(variant)){function chain(suffix){const nested=structuredClone(device);nested.ref='device:'+suffix;nested.objectIdentity='identity:'+suffix;nested.parentRef='chain:'+suffix;nested.parameters[0].ref='parameter:'+suffix;nested.parameters[0].objectIdentity='identity:param:'+suffix;return{ref:'chain:'+suffix,parentRef:device.ref,objectIdentity:'identity:chain:'+suffix,name:'Nested',devices:[nested]};}const chain1=chain('nested'),chain2=chain('pad');device.chains=[chain1];device.drumPads=[{ref:'drum-pad:pad',parentRef:device.ref,index:0,name:'Pad',chains:[chain2]}];args.parameterRef=variant==='nested-pad'?'parameter:pad':'parameter:nested';clip.envelopes['parameter:nested']=[{time:0,value:0.5}];clip.envelopes['parameter:pad']=[];}
if(variant==='rack-macro'||variant==='clear-macros'){device.macros=[{ref:'rack-macro:1',objectIdentity:'identity:macro',name:'Macro',value:0.5}];args.parameterRef='rack-macro:1';clip.envelopes['rack-macro:1']=[{time:0,value:0.5}];}
if(variant==='duplicate-parameter'||variant==='clear-duplicate')device.parameters.push(structuredClone(device.parameters[0]));if(variant==='conflicting-parameter')device.parameters.push({...structuredClone(device.parameters[0]),objectIdentity:'other'});if(variant==='missing-parameter-identity')delete device.parameters[0].objectIdentity;if(variant==='missing-device-identity')delete device.objectIdentity;if(variant==='missing-track-identity')delete track.objectIdentity;if(variant.startsWith('clear'))args={action:'clear-envelopes',clipRef:'clip:clip-1'};
const state=structuredClone(sim.state),host=new McpHost(sim);const result=await host.liveAutomationPreviewAsync(1,args);authorities.push({variant,state,args,result:clean(result)});}
fs.writeFileSync(new URL('host-automation-oracle.json.gz',import.meta.url),gzipSync(JSON.stringify({rows,workflows,evidence,authorities}),{level:9}));console.log({rows:rows.length,workflows:workflows.length});
